// Command side: enforces rules, owns the write path
public class OrderCommandModel {
    private String orderId;
    private String customerId;
    private List<OrderLine> lines;
    private OrderStatus status;

    public void place(List<OrderLine> lines, InventoryClient inventory) {
        if (lines.isEmpty()) {
            throw new IllegalArgumentException("Order needs at least one item");
        }
        for (OrderLine line : lines) {
            inventory.reserve(line.getSku(), line.getQuantity());
        }
        this.lines = lines;
        this.status = OrderStatus.PLACED;
    }
}

