public class PlaceOrderCommandHandler {
    private final OrderRepository orderRepository;
    private final InventoryClient inventory;
    private final EventPublisher events;

    public String handle(PlaceOrderCommand cmd) {
        for (OrderLine line : cmd.getLines()) {
            inventory.reserve(line.getSku(), line.getQuantity());
        }

        Order order = new Order(cmd.getCustomerId(), cmd.getLines());
        orderRepository.save(order); // normalized orders + order_items tables

        events.publish(new OrderPlacedEvent(order.getId(), order.getCustomerId(),
                order.getTotalAmount(), order.getLines().size()));

        return order.getId();
    }
}

