@EventListener
public class OrderSummaryProjector {
    private final OrderSummaryReadStore readStore;
    private final CustomerLookup customers;

    public void on(OrderPlacedEvent event) {
        String customerName = customers.getName(event.getCustomerId());

        readStore.upsert(new OrderSummaryModel(
                event.getOrderId(),
                customerName,
                event.getItemCount(),
                event.getTotalAmount(),
                "PLACED",
                Instant.now()
        ));
    }
}

